<?php
require __DIR__.'/app/bootstrap.php'; require __DIR__.'/app/tickets.php'; require __DIR__.'/app/layout.php'; $user=require_permission('edit_tickets');$id=(int)($_GET['id']??0);$q=db()->prepare('SELECT * FROM tickets WHERE id=? AND deleted_at IS NULL');$q->execute([$id]);$t=$q->fetch();if(!$t){http_response_code(404);exit('Ticket not found.');}
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$v=array_map(fn($x)=>trim((string)$x),$_POST);$subs=TICKET_CATEGORIES[$v['category']??'']??null;if($subs===null||($subs&&!in_array($v['subcategory']??'',$subs,true)))exit('Invalid category.');db()->prepare('UPDATE tickets SET issue_escalator=?,subject=?,category=?,subcategory=?,department_id=?,employee_name=?,description=? WHERE id=?')->execute([$v['issue_escalator'],$v['subject'],$v['category'],$v['subcategory']?:null,(int)$v['department_id'],$v['employee_name'],$v['description'],$id]);activity($id,$user['id'],'details_updated');notify_management('Ticket updated: '.$t['ticket_number'],$v['subject']);redirect('ticket.php?id='.$id);}
$departments=db()->query('SELECT id,name FROM departments ORDER BY name')->fetchAll();page_start('Edit ticket',$user);?><h1>Edit ticket</h1><form method="post" class="ticket-form"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><label>Issue Escalator<input name="issue_escalator" value="<?=e($t['issue_escalator'])?>" required></label><label>Subject<input name="subject" value="<?=e($t['subject'])?>" required></label><label>Category<select name="category"><?php foreach(TICKET_CATEGORIES as $c=>$s):?><option <?=$t['category']===$c?'selected':''?>><?=e($c)?></option><?php endforeach;?></select></label><label>Subcategory<input name="subcategory" value="<?=e($t['subcategory'])?>"></label><label>Department<select name="department_id"><?php foreach($departments as $d):?><option value="<?=$d['id']?>" <?=$t['department_id']==$d['id']?'selected':''?>><?=e($d['name'])?></option><?php endforeach;?></select></label><label>Employee<input name="employee_name" value="<?=e($t['employee_name'])?>" required></label><label>Description<textarea name="description" rows="6" required><?=e($t['description'])?></textarea></label><button class="button">Save ticket details</button></form><?php page_end();
